e-columns:1fr 1fr;gap:0 20px}.sec-info-row{display:grid;grid-template-columns:140px 1fr;gap:8px;padding:9px 2px;border-bottom:1px solid #edf1f5;font-size:12px}.sec-info-row strong{color:#43566d}.sec-tabs{display:flex;flex-wrap:wrap;gap:5px;padding:10px 15px;border-bottom:1px solid #e5ebf2}.sec-tabs a{padding:8px 10px;border-radius:4px;color:#4a6078;font-size:12px}.sec-tabs a:hover,.sec-tabs a.active{background:#eaf4ff;color:#087cf0}.sec-text-block{padding:14px 0;border-bottom:1px solid #edf1f5}.sec-text-block:last-child{border:0}.sec-text-block h3{font-size:14px!important;margin-bottom:8px}.sec-text-block p{margin:0;color:#526579;font-size:13px!important;line-height:1.65;white-space:pre-line}.sec-evidence-list{display:grid;gap:8px}.sec-evidence-item{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px;border:1px solid #e4ebf3;border-radius:5px;background:#fbfcfe;font-size:12px}.sec-timeline{display:grid;gap:0}.sec-timeline-item{position:relative;padding:0 0 18px 23px;border-left:2px solid #d9e8f6;margin-left:7px}.sec-timeline-item:last-child{border-left-color:transparent;padding-bottom:0}.sec-timeline-item:before{content:'';position:absolute;left:-7px;top:1px;width:12px;height:12px;border:2px solid #fff;border-radius:50%;background:#087cf0;box-shadow:0 0 0 1px #087cf0}.sec-timeline-item p{margin:4px 0;color:#617287;font-size:12px!important}.sec-timeline-item time{font-size:11px;color:#8a98a8}.sec-empty{padding:35px;text-align:center;color:#8291a3}.sec-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.sec-required{color:#d73b49}.security-page .alert{font-size:13px!important}
